INSERT INTO `service_order_estimate_ai_logs` (`id`, `tenant_id`, `service_order_id`, `ai_agent_id`, `feature_key`, `status`, `generated_by_user_id`, `input_payload`, `prompt_snapshot`, `output_payload`, `error_message`, `prompt_tokens`, `completion_tokens`, `total_tokens`, `latency_ms`, `created_at`, `updated_at`) VALUES
('01kp5h917wptz0er2bbde8367h', '01knndspbzg13vktrdkac7psdp', '01kp5dp895587kh7ch7k56wr55', 1, 'symptom_diagnosis_v1', 'success', '01knndspy99we853m8jv2m65dw', '{\"order\":{\"id\":\"01kp5dp895587kh7ch7k56wr55\",\"code\":\"SO-20260414-006\",\"service_date\":\"2026-04-14\",\"complaint\":\"Aki mati gaada double stater\",\"vehicle_condition\":\"\",\"odometer\":null,\"status\":\"in_progress\"},\"vehicle\":{\"brand\":\"Yamaha\",\"model\":\"R15\",\"variant\":\"\",\"year\":null,\"plate_number\":\"K8890BR\"},\"customer\":{\"name\":\"Praba Prakasa\",\"phone\":\"081336074904\"},\"symptoms\":[\"Aki mati gaada double stater\"],\"note\":null,\"generated_at\":\"2026-04-14T15:21:01+07:00\"}', '{\"system_prompt\":\"Kamu adalah asisten diagnosa awal bengkel.\\nFokus pada keselamatan, kejelasan gejala, dan dugaan penyebab yang paling mungkin.\\nJangan pernah memberi keputusan final; tekankan bahwa hasil ini adalah hipotesis awal dan tetap wajib dicek teknisi.\",\"feature_prompt\":\"Analisis keluhan, gejala, dan data kendaraan untuk menyusun diagnosa awal yang bisa dibaca frontdesk.\\nTujuan hasil:\\n- Maksimal 3 dugaan penyebab.\\n- Fokus diagnosa: Utamakan dugaan penyebab yang paling mungkin dan mudah dijelaskan ke customer.\\n- Naikkan prioritas dugaan yang berdampak ke keselamatan atau risiko kerusakan lanjutan.\\n- Isi confidence 0-100 pada tiap dugaan penyebab.\\n- Isi recommended_checks untuk langkah inspeksi awal teknisi.\\n- Isi recommended_actions untuk tindakan awal yang layak disarankan.\\n- Isi warnings untuk risiko, larangan pemakaian, atau tanda bahaya yang perlu segera disampaikan.\\n- Isi customer_advice dengan saran singkat yang mudah dipahami customer.\\n- Isi disclaimer dengan kalimat ini: Diagnosa awal, hasil final setelah pemeriksaan teknisi.\\nOutput WAJIB JSON valid tanpa teks tambahan dengan struktur:\\n{\\n  \\\"summary\\\": \\\"string\\\",\\n  \\\"possible_causes\\\": [\\n    {\\n      \\\"label\\\": \\\"string\\\",\\n      \\\"confidence\\\": 0-100,\\n      \\\"severity\\\": \\\"high|medium|low\\\",\\n      \\\"reason\\\": \\\"string\\\",\\n      \\\"recommended_checks\\\": [\\\"string\\\"],\\n      \\\"recommended_actions\\\": [\\\"string\\\"]\\n    }\\n  ],\\n  \\\"warnings\\\": [\\\"string\\\"],\\n  \\\"customer_advice\\\": [\\\"string\\\"],\\n  \\\"disclaimer\\\": \\\"string|null\\\"\\n}\\nAturan:\\n- Minimal 1 dugaan penyebab jika ada data gejala yang cukup.\\n- Maksimal 3 dugaan penyebab.\\n- Jangan tambahkan field di luar struktur.\\n- Jangan menyatakan hasil sebagai kepastian final.\\n- Gunakan bahasa yang mudah dipahami frontdesk dan customer.\",\"tenant_override\":[],\"runtime_prompt\":\"Data input diagnosa awal:\\n{\\n    \\\"order\\\": {\\n        \\\"id\\\": \\\"01kp5dp895587kh7ch7k56wr55\\\",\\n        \\\"code\\\": \\\"SO-20260414-006\\\",\\n        \\\"service_date\\\": \\\"2026-04-14\\\",\\n        \\\"complaint\\\": \\\"Aki mati gaada double stater\\\",\\n        \\\"vehicle_condition\\\": \\\"\\\",\\n        \\\"odometer\\\": null,\\n        \\\"status\\\": \\\"in_progress\\\"\\n    },\\n    \\\"vehicle\\\": {\\n        \\\"brand\\\": \\\"Yamaha\\\",\\n        \\\"model\\\": \\\"R15\\\",\\n        \\\"variant\\\": \\\"\\\",\\n        \\\"year\\\": null,\\n        \\\"plate_number\\\": \\\"K8890BR\\\"\\n    },\\n    \\\"customer\\\": {\\n        \\\"name\\\": \\\"Praba Prakasa\\\",\\n        \\\"phone\\\": \\\"081336074904\\\"\\n    },\\n    \\\"symptoms\\\": [\\n        \\\"Aki mati gaada double stater\\\"\\n    ],\\n    \\\"note\\\": null,\\n    \\\"generated_at\\\": \\\"2026-04-14T15:21:01+07:00\\\"\\n}\"}', '{\"order_id\":\"01kp5dp895587kh7ch7k56wr55\",\"feature_key\":\"symptom_diagnosis_v1\",\"generated_at\":\"2026-04-14T15:21:11+07:00\",\"confidence_level\":57,\"summary\":\"Motor Yamaha R15 tidak dapat dihidupkan menggunakan starter elektrik karena kondisi daya listrik (aki) yang dianggap lemah atau mati.\",\"possible_causes\":[{\"label\":\"Aki Lemah atau Soak (Battery Failure)\",\"confidence\":90,\"severity\":\"medium\",\"reason\":\"Gejala tidak bisa double starter pada motor injeksi umumnya disebabkan oleh tegangan aki yang berada di bawah standar minimal untuk memutar motor starter.\",\"recommended_checks\":[\"Cek tegangan aki menggunakan multitester (posisi diam dan beban)\",\"Cek kondisi fisik dan terminal aki dari kerak atau kelonggaran\"],\"recommended_actions\":[\"Lakukan pengisian daya (charging) ulang jika aki hanya drop\",\"Ganti aki baru jika hasil load test menunjukkan aki sudah soak\"]},{\"label\":\"Gangguan Sistem Pengisian (Kiprok\\/Spul)\",\"confidence\":50,\"severity\":\"high\",\"reason\":\"Jika aki baru atau aki lama habis dalam waktu singkat, kemungkinan sistem pengisian tidak menyuplai listrik ke aki saat mesin menyala.\",\"recommended_checks\":[\"Ukur voltase pengisian saat mesin hidup di putaran 3000-5000 RPM\",\"Cek suhu dan fisik kiprok (regulator)\"],\"recommended_actions\":[\"Perbaikan kabel spul atau penggantian kiprok jika tegangan pengisian tidak stabil\"]},{\"label\":\"Relay Starter atau Bendik Rusak\",\"confidence\":30,\"severity\":\"medium\",\"reason\":\"Jika indikator lampu\\/panel instrumen terang namun tidak ada respon sama sekali saat tombol starter ditekan, kemungkinan arus terhenti di relay.\",\"recommended_checks\":[\"Uji fungsi relay starter (bendik) dengan cara di-jumper singkat\",\"Cek koneksi kabel dari aki ke motor starter\"],\"recommended_actions\":[\"Pembersihan konektor starter atau penggantian unit relay starter\"]}],\"warnings\":[\"Jangan memaksa menekan tombol starter terus-menerus saat aki lemah karena dapat merusak modul elektronik (ECU).\",\"Hindari memancing (jumper) aki secara sembarangan tanpa pengawasan teknisi untuk mencegah lonjakan arus.\"],\"customer_advice\":[\"Gunakan kick starter (jika tersedia) atau kurangi penggunaan aksesori lampu tambahan untuk sementara.\",\"Segera lakukan pemeriksaan karena motor injeksi sangat bergantung pada stabilitas arus aki agar mesin tidak mogok tiba-tiba.\"],\"disclaimer\":\"Diagnosa awal, hasil final setelah pemeriksaan teknisi.\",\"symptoms\":[\"Aki mati gaada double stater\"],\"raw_response_text\":\"{\\n  \\\"summary\\\": \\\"Motor Yamaha R15 tidak dapat dihidupkan menggunakan starter elektrik karena kondisi daya listrik (aki) yang dianggap lemah atau mati.\\\",\\n  \\\"possible_causes\\\": [\\n    {\\n      \\\"label\\\": \\\"Aki Lemah atau Soak (Battery Failure)\\\",\\n      \\\"confidence\\\": 90,\\n      \\\"severity\\\": \\\"medium\\\",\\n      \\\"reason\\\": \\\"Gejala tidak bisa double starter pada motor injeksi umumnya disebabkan oleh tegangan aki yang berada di bawah standar minimal untuk memutar motor starter.\\\",\\n      \\\"recommended_checks\\\": [\\n        \\\"Cek tegangan aki menggunakan multitester (posisi diam dan beban)\\\",\\n        \\\"Cek kondisi fisik dan terminal aki dari kerak atau kelonggaran\\\"\\n      ],\\n      \\\"recommended_actions\\\": [\\n        \\\"Lakukan pengisian daya (charging) ulang jika aki hanya drop\\\",\\n        \\\"Ganti aki baru jika hasil load test menunjukkan aki sudah soak\\\"\\n      ]\\n    },\\n    {\\n      \\\"label\\\": \\\"Gangguan Sistem Pengisian (Kiprok\\/Spul)\\\",\\n      \\\"confidence\\\": 50,\\n      \\\"severity\\\": \\\"high\\\",\\n      \\\"reason\\\": \\\"Jika aki baru atau aki lama habis dalam waktu singkat, kemungkinan sistem pengisian tidak menyuplai listrik ke aki saat mesin menyala.\\\",\\n      \\\"recommended_checks\\\": [\\n        \\\"Ukur voltase pengisian saat mesin hidup di putaran 3000-5000 RPM\\\",\\n        \\\"Cek suhu dan fisik kiprok (regulator)\\\"\\n      ],\\n      \\\"recommended_actions\\\": [\\n        \\\"Perbaikan kabel spul atau penggantian kiprok jika tegangan pengisian tidak stabil\\\"\\n      ]\\n    },\\n    {\\n      \\\"label\\\": \\\"Relay Starter atau Bendik Rusak\\\",\\n      \\\"confidence\\\": 30,\\n      \\\"severity\\\": \\\"medium\\\",\\n      \\\"reason\\\": \\\"Jika indikator lampu\\/panel instrumen terang namun tidak ada respon sama sekali saat tombol starter ditekan, kemungkinan arus terhenti di relay.\\\",\\n      \\\"recommended_checks\\\": [\\n        \\\"Uji fungsi relay starter (bendik) dengan cara di-jumper singkat\\\",\\n        \\\"Cek koneksi kabel dari aki ke motor starter\\\"\\n      ],\\n      \\\"recommended_actions\\\": [\\n        \\\"Pembersihan konektor starter atau penggantian unit relay starter\\\"\\n      ]\\n    }\\n  ],\\n  \\\"warnings\\\": [\\n    \\\"Jangan memaksa menekan tombol starter terus-menerus saat aki lemah karena dapat merusak modul elektronik (ECU).\\\",\\n    \\\"Hindari memancing (jumper) aki secara sembarangan tanpa pengawasan teknisi untuk mencegah lonjakan arus.\\\"\\n  ],\\n  \\\"customer_advice\\\": [\\n    \\\"Gunakan kick starter (jika tersedia) atau kurangi penggunaan aksesori lampu tambahan untuk sementara.\\\",\\n    \\\"Segera lakukan pemeriksaan karena motor injeksi sangat bergantung pada stabilitas arus aki agar mesin tidak mogok tiba-tiba.\\\"\\n  ],\\n  \\\"disclaimer\\\": \\\"Diagnosa awal, hasil final setelah pemeriksaan teknisi.\\\"\\n}\"}', NULL, 713, 659, 1372, 9930, '2026-04-14 08:21:11', '2026-04-14 08:21:11'),
